import{_ as o,o as e,c as i,a2 as s}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Programa Fundamental do Progresso Conjunto das Dez Mil Raças","description":"","frontmatter":{},"headers":[],"relativePath":"pt/05-万族共进基本纲领.md","filePath":"pt/05-万族共进基本纲领.md","lastUpdated":1789183869000}'),r={name:"pt/05-万族共进基本纲领.md"};function t(d,a,n,c,l,u){return e(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="programa-fundamental-do-progresso-conjunto-das-dez-mil-racas" tabindex="-1">Programa Fundamental do Progresso Conjunto das Dez Mil Raças <a class="header-anchor" href="#programa-fundamental-do-progresso-conjunto-das-dez-mil-racas" aria-label="Permalink to &quot;Programa Fundamental do Progresso Conjunto das Dez Mil Raças&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projeto</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do Documento</td><td>05</td></tr><tr><td>Módulo</td><td>Princípios Gerais e Configuração Central</td></tr><tr><td>Palavras-chave</td><td>Dez Mil Raças, Progresso Conjunto, Igualdade Racial, Evolução Cooperativa, República</td></tr></tbody></table><h2 id="i-definicao-e-ambito-das-dez-mil-racas" tabindex="-1">I. Definição e Âmbito das Dez Mil Raças <a class="header-anchor" href="#i-definicao-e-ambito-das-dez-mil-racas" aria-label="Permalink to &quot;I. Definição e Âmbito das Dez Mil Raças&quot;">​</a></h2><p>&quot;Dez Mil Raças&quot; é a designação geral de todas as formas de vida com potencial de percepção e evolução no Cosmos Original dos Dez Mil Espíritos e da Âncora Equilibrada. &quot;Dez Mil&quot; não se refere exatamente a dez mil raças, mas exprime a sua multiplicidade, abrangendo todas as formas de vida conhecidas e desconhecidas. O âmbito das Dez Mil Raças inclui, mas não se limita a: a Raça Humana e várias raças humanoides, vidas de energia, entidades de consciência, vidas mecânicas, vidas inteligentes de tipo vegetal, vidas anómalas, raças mestiças interplanares, etc.</p><p>A civilização simbiótica defende o princípio da &quot;igualdade das formas de vida&quot;, não utilizando a constituição material, o nível energético ou a complexidade da consciência da vida como critério para dividir o elevado e o baixo, o nobre e o humilde. Qualquer raça, independentemente do nível médio de cultivo dos seus indivíduos, do tamanho da sua população ou da duração da sua história, goza de estatuto e direitos iguais na civilização simbiótica.</p><h2 id="ii-a-ideia-central-do-progresso-conjunto-das-dez-mil-racas" tabindex="-1">II. A Ideia Central do Progresso Conjunto das Dez Mil Raças <a class="header-anchor" href="#ii-a-ideia-central-do-progresso-conjunto-das-dez-mil-racas" aria-label="Permalink to &quot;II. A Ideia Central do Progresso Conjunto das Dez Mil Raças&quot;">​</a></h2><p>O progresso conjunto das Dez Mil Raças é um dos objetivos centrais da Civilização Simbiótica da Âncora, e a sua ideia fundamental pode ser resumida nos seguintes quatro pontos:</p><ol><li><strong>A evolução não é um jogo de soma zero entre raças</strong>: A evolução de uma raça não custa a vida de outras raças; pelo contrário, a cooperação entre raças pode gerar efeitos de evolução sinérgica.</li><li><strong>Cada raça tem vantagens evolutivas únicas</strong>: Diferentes raças desenvolveram as suas próprias características e talentos ao longo de uma longa evolução, e essas características são um recurso valioso para a diversidade evolutiva do cosmos.</li><li><strong>As raças atrasadas têm direito a receber apoio</strong>: Para as raças com um nível evolutivo mais baixo, a civilização simbiótica tem a obrigação de fornecer apoio em educação, recursos, tecnologia, etc., ajudando-as a encontrar o seu próprio caminho evolutivo.</li><li><strong>As raças avançadas têm a obrigação de assumir responsabilidades</strong>: As raças com um nível evolutivo mais elevado assumem mais responsabilidades públicas na civilização simbiótica, incluindo a manutenção dos pontos de âncora, a transmissão de conhecimentos, a proteção da civilização, etc.</li></ol><h2 id="iii-principios-fundamentais-do-progresso-conjunto-das-dez-mil-racas" tabindex="-1">III. Princípios Fundamentais do Progresso Conjunto das Dez Mil Raças <a class="header-anchor" href="#iii-principios-fundamentais-do-progresso-conjunto-das-dez-mil-racas" aria-label="Permalink to &quot;III. Princípios Fundamentais do Progresso Conjunto das Dez Mil Raças&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Princípio</th><th>Conteúdo</th><th>Requisitos Específicos</th></tr></thead><tbody><tr><td>Princípio da Igualdade Racial</td><td>Todas as raças são iguais em estatuto jurídico e direito evolutivo</td><td>Proibição da discriminação racial, cargos públicos abertos a todas as raças</td></tr><tr><td>Princípio do Respeito Cultural</td><td>Respeito pelas tradições culturais e modos de vida de cada raça</td><td>Não forçar a assimilação cultural, apoiar a transmissão e o desenvolvimento da cultura racial</td></tr><tr><td>Princípio da Complementaridade de Vantagens</td><td>Incentivar as raças a colaborar utilizando as suas próprias vantagens</td><td>Criar base de dados de especialidades raciais, promover projetos de cooperação inter-racial</td></tr><tr><td>Princípio do Apoio aos Atrasados</td><td>Conceder apoio adicional às raças com nível evolutivo mais baixo</td><td>Criar fundo de desenvolvimento racial, fornecer educação direcionada e distribuição de recursos</td></tr><tr><td>Princípio da Autonomia e Cogovernação</td><td>Assuntos internos da raça são autónomos, assuntos inter-raciais são cogovernados</td><td>Cada raça tem poder legislativo interno, assuntos públicos são decididos por instituições republicanas</td></tr><tr><td>Princípio da Resolução Pacífica de Conflitos</td><td>Conflitos inter-raciais são resolvidos por meios pacíficos</td><td>Proibição de guerras inter-raciais, conflitos são submetidos à arbitragem do Tribunal da Âncora</td></tr></tbody></table><h2 id="iv-caminho-de-implementacao-do-progresso-conjunto-das-dez-mil-racas" tabindex="-1">IV. Caminho de Implementação do Progresso Conjunto das Dez Mil Raças <a class="header-anchor" href="#iv-caminho-de-implementacao-do-progresso-conjunto-das-dez-mil-racas" aria-label="Permalink to &quot;IV. Caminho de Implementação do Progresso Conjunto das Dez Mil Raças&quot;">​</a></h2><p>O progresso conjunto das Dez Mil Raças não é um slogan, mas é implementado gradualmente através dos seguintes caminhos específicos:</p><h3 id="_4-1-educacao-comum" tabindex="-1">4.1 Educação Comum <a class="header-anchor" href="#_4-1-educacao-comum" aria-label="Permalink to &quot;4.1 Educação Comum&quot;">​</a></h3><p>Criar um sistema de educação simbiótica inter-racial, onde os juvenis de todas as raças podem receber gratuitamente educação evolutiva básica. O conteúdo educacional inclui os métodos básicos dos Trezentos Sistemas de Cultivo, a ética anti-predatória, a Constituição da Civilização Simbiótica, conhecimentos gerais do cosmos, etc. Ao mesmo tempo, respeitar as tradições educacionais culturais de cada raça, permitindo a realização de educação com características raciais para além da educação comum.</p><h3 id="_4-2-partilha-de-recursos" tabindex="-1">4.2 Partilha de Recursos <a class="header-anchor" href="#_4-2-partilha-de-recursos" aria-label="Permalink to &quot;4.2 Partilha de Recursos&quot;">​</a></h3><p>Através do sistema de contrato vinculado à produção, distribuir de forma integrada os recursos de cultivo cósmicos de acordo com a população racial, as necessidades evolutivas e o grau de contribuição. Para as raças com escassez de recursos, realizar a distribuição interplanar de recursos através da rede de pontos de âncora. Proibir qualquer raça de monopolizar os recursos públicos de cultivo.</p><h3 id="_4-3-investigacao-tecnologica-conjunta" tabindex="-1">4.3 Investigação Tecnológica Conjunta <a class="header-anchor" href="#_4-3-investigacao-tecnologica-conjunta" aria-label="Permalink to &quot;4.3 Investigação Tecnológica Conjunta&quot;">​</a></h3><p>Incentivar a investigação cooperativa tecnológica inter-racial, especialmente projetos de investigação que combinem as capacidades inatas de diferentes raças com a engenharia das leis. A civilização simbiótica cria o &quot;Fundo de Investigação Conjunta das Dez Mil Raças&quot;, financiando equipas de investigação inter-raciais. Os resultados da investigação são abertos gratuitamente a todas as raças.</p><h3 id="_4-4-mobilidade-de-talentos" tabindex="-1">4.4 Mobilidade de Talentos <a class="header-anchor" href="#_4-4-mobilidade-de-talentos" aria-label="Permalink to &quot;4.4 Mobilidade de Talentos&quot;">​</a></h3><p>Quebrar as barreiras de talentos entre raças, permitindo que os cultivadores circulem e troquem livremente entre as áreas de povoamento de diferentes raças. Criar um sistema de mentores inter-raciais, onde cultivadores avançados podem orientar cultivadores iniciantes de outras raças.</p><h3 id="_4-5-participacao-republicana" tabindex="-1">4.5 Participação Republicana <a class="header-anchor" href="#_4-5-participacao-republicana" aria-label="Permalink to &quot;4.5 Participação Republicana&quot;">​</a></h3><p>O Parlamento da República das Dez Mil Raças distribui os assentos de forma integrada de acordo com a população racial e o grau de contribuição, garantindo que as raças pequenas também tenham canal de voz. As decisões do parlamento adotam uma combinação de consenso por negociação e votação maioritária, e os assuntos relacionados com os interesses fundamentais de uma raça exigem o consentimento da raça relevante.</p><h2 id="v-politicas-para-racas-especiais" tabindex="-1">V. Políticas para Raças Especiais <a class="header-anchor" href="#v-politicas-para-racas-especiais" aria-label="Permalink to &quot;V. Políticas para Raças Especiais&quot;">​</a></h2><p>Para raças em situações especiais, a civilização simbiótica adota políticas diferenciadas:</p><ul><li><strong>Raças em Perigo</strong>: Criar plano de proteção racial, fornecer apoio de recursos de emergência e proteção de habitat, ajudando-as a recuperar a população</li><li><strong>Raças de Vida Anómala</strong>: Avaliar e alojar de acordo com o fluxo de tratamento padronizado de três tipos de vida anómala, garantindo que o seu direito evolutivo seja protegido</li><li><strong>Raças Mestiças Interplanares</strong>: Reconhecer a sua dupla identidade racial, garantir os seus direitos iguais em ambas as culturas raciais</li><li><strong>Raças Ex-Predadoras</strong>: Para as raças que historicamente praticaram o predacionismo, após completarem a transformação ética e a conversão do sistema, conceder estatuto completamente igual, não praticar discriminação de retrospetiva histórica</li></ul><h2 id="vi-indicadores-de-medicao-do-progresso-conjunto-das-dez-mil-racas" tabindex="-1">VI. Indicadores de Medição do Progresso Conjunto das Dez Mil Raças <a class="header-anchor" href="#vi-indicadores-de-medicao-do-progresso-conjunto-das-dez-mil-racas" aria-label="Permalink to &quot;VI. Indicadores de Medição do Progresso Conjunto das Dez Mil Raças&quot;">​</a></h2><p>A civilização simbiótica criou o &quot;Índice de Progresso Conjunto das Dez Mil Raças&quot;, medindo o progresso do progresso conjunto das Dez Mil Raças a partir das seguintes dimensões:</p><table tabindex="0"><thead><tr><th>Dimensão</th><th>Indicador</th><th>Objetivo</th></tr></thead><tbody><tr><td>Taxa de Cobertura Evolutiva</td><td>Proporção de raças conectadas ao sistema de cultivo</td><td>100%</td></tr><tr><td>Grau de Equilíbrio de Nível</td><td>Coeficiente de diferença do nível médio de cada raça</td><td>Diminuir continuamente</td></tr><tr><td>Densidade de Cooperação</td><td>Número e profundidade de projetos de cooperação inter-racial</td><td>Aumentar continuamente</td></tr><tr><td>Vitalidade Cultural</td><td>Atividade de transmissão e inovação cultural racial</td><td>Manter a diversidade</td></tr><tr><td>Taxa de Ocorrência de Conflitos</td><td>Frequência de ocorrência de conflitos inter-raciais</td><td>Diminuir continuamente</td></tr></tbody></table><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>O progresso conjunto das Dez Mil Raças é um dos objetivos últimos da Civilização Simbiótica da Âncora e também uma condição necessária para a ascensão dimensional global do cosmos. No quadro da civilização simbiótica, cada raça pode encontrar o seu próprio caminho evolutivo, e a singularidade de cada raça pode ser respeitada e expressa. O progresso conjunto das Dez Mil Raças não significa eliminar as diferenças, mas alcançar a harmonia nas diferenças e realizar a simbiose na diversidade.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (Declaração da Civilização Simbiótica da Âncora)</li><li>50-万族谱系总览 (Visão Geral da Genealogia das Dez Mil Raças)</li><li>77-万族共和成立 (Fundação da República das Dez Mil Raças)</li></ul>',32)])])}const v=o(r,[["render",t]]);export{p as __pageData,v as default};
